# Let me check if there's pattern on 3x3 or 9x9 blocks
# Also check for row/column patterns

# Check 9x9 grids
def analyze_9x9_blocks(grid, size=19):
    n = size // 3
    print(f"Grid is {size}x{size}, split into 3x3 blocks of {n}x{n}")

    for block_r in range(3):
        for block_c in range(3):
            block = [row[block_r*n:(block_r+1)*n] for row in grid[block_c*n:(block_c+1)*n]]
            # Count non-8 colors
            non8 = []
            for r, row in enumerate(block):
                for c, val in enumerate(row):
                    if val != 8:
                        non8.append((r + block_c*n, c + block_r*n, val))

            print(f"Block at ({block_r}, {block_c}): {len(non8)} non-8 cells")
            if len(non8) > 10:
                print(f"  Non-8: {non8}")

analyze_9x9_blocks(grid)

# Also check if each row has specific patterns
print("\n=== Row analysis ===")
for i, row in enumerate(grid):
    non8 = [(j, val) for j, val in enumerate(row) if val != 8]
    if len(non8) > 0:
        print(f"Row {i}: {len(non8)} non-8: {[v for _, v in non8]}")

print("\n=== Col analysis ===")
for c in range(19):
    non8 = [(r, grid[r][c]) for r in range(19) if grid[r][c] != 8]
    if len(non8) > 0:
        print(f"Col {c}: {len(non8)} non-8")

